Of course. Here is an optimized and heavily commented JSX script for Adobe InDesign that accomplishes your goal.

This script is designed to be robust and user-friendly. It handles various document setups, provides visual feedback in the new document, and organizes the new content onto separate, non-printing layers for clarity.

### Key Features of this Script:

*   **Creates a New Document:** Your original document is left untouched.
*   **Single Tall Page:** Calculates the required height to fit all original spreads and creates one long page.
*   **Preserves Positioning:** All page items (text frames, images, shapes, groups) are moved to their exact relative positions. It correctly handles items on both left and right pages of a spread.
*   **Visual Guides Layer:** Creates a non-printing layer named "Original Page Guides" and draws rectangles representing the boundaries and margins of every original page. This visually preserves the original layout structure.
*   **Master Page Info Layer:** Creates another non-printing layer named "Page Info" and adds a text label for each original page, indicating its page number and the name of the Master Page it was based on.
*   **Configurable:** A configuration object at the top of the script allows you to easily change the vertical gap between spreads, layer names, and other settings.
*   **Undoable:** The entire operation is wrapped in a single "Undo" step.
*   **Optimized:** Uses efficient methods for duplicating and moving objects to handle large documents gracefully.

---

### The Script: `transformToSinglePage.jsx`

```javascript
// transformToSinglePage.jsx
// Copyright (c) 2023, [Your Name/Studio]
//
// DESCRIPTION:
// This script transforms an InDesign document with multiple spreads/pages into a new document
// with a single, long-format page. It preserves the original layout, positioning,
// margins (as visual guides), and provides information about the original master page applied to each section.
//
// USAGE:
// 1. Open the InDesign document you want to transform.
// 2. Run this script via File > Scripts > Other Script... (or place it in your Scripts Panel).
// 3. A new document will be created with the transformed layout.
//
//---------------------------------------------------------------------------------

#target indesign

// Configuration object - easily change settings here
var config = {
    VERTICAL_GAP: 20, // The space (in document units) between each original spread
    GUIDE_LAYER_NAME: "Original Page Guides",
    INFO_LAYER_NAME: "Page Info",
    GUIDE_COLOR: "LIGHT_BLUE", // InDesign UI color name for guide rectangles
    MARGIN_COLOR: "MAGENTA",   // InDesign UI color name for margin rectangles
    LABEL_FONT_SIZE: "8pt"
};

// Main function to encapsulate the script's logic
function main() {
    if (app.documents.length === 0) {
        alert("Error: Please open a document before running this script.");
        return;
    }

    var sourceDoc = app.activeDocument;

    // Use app.doScript for a single undo step and better performance
    app.doScript(
        function() {
            transformDocument(sourceDoc);
        },
        ScriptLanguage.JAVASCRIPT,
        undefined,
        UndoModes.ENTIRE_SCRIPT,
        "Transform to Single Page"
    );
}

// The core logic of the transformation process
function transformDocument(sourceDoc) {
    // 1. ANALYZE SOURCE DOCUMENT
    //--------------------------------------------------
    var totalHeight = 0;
    var maxWidth = 0;
    var spreadData = [];

    // Loop through all spreads to calculate the dimensions of the new page
    for (var i = 0; i < sourceDoc.spreads.length; i++) {
        var spread = sourceDoc.spreads[i];
        var sBounds = spread.pages[0].bounds; // Use first page bounds as a reference for spread height
        var spreadHeight = sBounds[2] - sBounds[0];

        // Calculate the total width of the spread by getting the bounds of all its pages
        var spreadWidth = 0;
        for (var j = 0; j < spread.pages.length; j++) {
             spreadWidth += spread.pages[j].bounds[3] - spread.pages[j].bounds[1];
        }

        maxWidth = Math.max(maxWidth, spreadWidth);
        totalHeight += spreadHeight;
        spreadData.push({ height: spreadHeight, spreadRef: spread });

        // Add the gap, but not after the last spread
        if (i < sourceDoc.spreads.length - 1) {
            totalHeight += config.VERTICAL_GAP;
        }
    }

    // 2. CREATE NEW DOCUMENT
    //--------------------------------------------------
    var newDoc = app.documents.add();
    newDoc.documentPreferences.properties = {
        facingPages: false,
        pageWidth: maxWidth,
        pageHeight: totalHeight
    };

    var newPage = newDoc.pages[0];

    // Set the margins of the new page to match the first page of the source document
    var firstPageMargins = sourceDoc.pages[0].marginPreferences;
    newPage.marginPreferences.properties = {
        top: firstPageMargins.top,
        bottom: firstPageMargins.bottom,
        left: firstPageMargins.left,
        right: firstPageMargins.right
    };

    // 3. CREATE HELPER LAYERS
    //--------------------------------------------------
    var guideLayer = newDoc.layers.add({ name: config.GUIDE_LAYER_NAME, printable: false });
    var infoLayer = newDoc.layers.add({ name: config.INFO_LAYER_NAME, printable: false });

    // Set layer colors for better UI visibility
    try {
        guideLayer.layerColor = UIColors[config.GUIDE_COLOR.toUpperCase()];
        infoLayer.layerColor = UIColors.GRAY;
    } catch(e) {/* Color name might be invalid, ignore */}


    // 4. TRANSFER CONTENT AND CREATE GUIDES
    //--------------------------------------------------
    var currentYOffset = 0;

    for (var k = 0; k < spreadData.length; k++) {
        var currentSpread = spreadData[k].spreadRef;
        var spreadHeight = spreadData[k].height;
        var spreadXOffset = (maxWidth - (currentSpread.pages[-1].bounds[3] - currentSpread.pages[0].bounds[1])) / 2; // Center spreads if they have different widths

        // --- A. COPY SPREAD ITEMS ---
        var allSpreadItems = currentSpread.pageItems.everyItem().getElements();
        for (var m = 0; m < allSpreadItems.length; m++) {
            var item = allSpreadItems[m];

            // Duplicate the item onto the new page
            var newItem = item.duplicate(newPage);

            // Move the item into its new position using a transformation matrix
            // This is the most reliable way to move items, preserving all transformations.
            // The item is moved by (spreadXOffset, currentYOffset).
            var transformationMatrix = app.transformationMatrices.add({horizontalTranslation: spreadXOffset, verticalTranslation: currentYOffset});
            newItem.transform(CoordinateSpaces.PASTEBOARD_COORDINATES, AnchorPoint.CENTER_ANCHOR, transformationMatrix);
        }

        // --- B. CREATE VISUAL GUIDES AND INFO LABELS ---
        for (var p = 0; p < currentSpread.pages.length; p++) {
            var originalPage = currentSpread.pages[p];
            var pBounds = originalPage.bounds; // [y1, x1, y2, x2] relative to the spread
            var pMargins = originalPage.marginPreferences;

            // Calculate new positions for the guide rectangles
            var pageGuideBounds = [
                pBounds[0] + currentYOffset,
                pBounds[1] + spreadXOffset,
                pBounds[2] + currentYOffset,
                pBounds[3] + spreadXOffset
            ];
            var marginGuideBounds = [
                pageGuideBounds[0] + pMargins.top,
                pageGuideBounds[1] + pMargins.left,
                pageGuideBounds[2] - pMargins.bottom,
                pageGuideBounds[3] - pMargins.right
            ];

            // Draw the page boundary rectangle
            var pageRect = newPage.rectangles.add(guideLayer, {
                geometricBounds: pageGuideBounds,
                strokeWeight: 0,
                fillColor: newDoc.swatches.itemByName("None")
            });
            // Draw the margin boundary rectangle
            var marginRect = newPage.rectangles.add(guideLayer, {
                geometricBounds: marginGuideBounds,
                strokeWeight: "0.5pt",
                strokeColor: newDoc.colors.itemByName(config.MARGIN_COLOR),
                fillColor: newDoc.swatches.itemByName("None")
            });

            // Create the info label
            var masterName = originalPage.appliedMaster ? originalPage.appliedMaster.name : "None";
            var labelText = "Source Page: " + originalPage.name + "\nMaster: " + masterName;

            var labelFrame = newPage.textFrames.add(infoLayer, {
                geometricBounds: [pageGuideBounds[0], pageGuideBounds[1], pageGuideBounds[0] + 20, pageGuideBounds[1] + 100], // Position at top-left
                contents: labelText
            });
            labelFrame.textFramePreferences.verticalJustification = VerticalJustification.TOP_ALIGN;
            labelFrame.parentStory.pointSize = config.LABEL_FONT_SIZE;
            labelFrame.parentStory.fillColor = newDoc.colors.itemByName("Registration");
        }

        // Update the Y offset for the next spread
        currentYOffset += spreadHeight + config.VERTICAL_GAP;
    }

    alert("Transformation Complete!\n\nA new document named '" + newDoc.name + "' has been created.");
}

// Run the script
main();
```

